"""Alert icons rendered from Noto Color Emoji (SD 16x16 + HD 32x32).

Generated with: scripts/emoji_to_icon.py

Icons are pre-rendered from the Noto Color Emoji font (SIL OFL).
https://fonts.google.com/noto/specimen/Noto+Color+Emoji

SD icons (16x16) are used for 128x32 displays.
HD icons (32x32) are used for 256x64 displays.

Available icons:
    beacon: 🚨
    person: 🚶
    vehicle: 🚗
    animal: 🐾
    motion: 💨
    warning: ⚠️
    camera: 📷
    info: ℹ️
"""

from typing import Dict, Optional

from PIL import Image

# === SD Icons (16x16) ===

_BEACON_HEX = ""

_PERSON_HEX = ""

_VEHICLE_HEX = ""

_ANIMAL_HEX = ""

_MOTION_HEX = ""

_WARNING_HEX = ""

_CAMERA_HEX = ""

_INFO_HEX = ""


# === HD Icons (32x32) ===

_BEACON_HD_HEX = ""

_PERSON_HD_HEX = ""

_VEHICLE_HD_HEX = ""

_ANIMAL_HD_HEX = ""

_MOTION_HD_HEX = ""

_WARNING_HD_HEX = ""

_CAMERA_HD_HEX = ""

_INFO_HD_HEX = ""


def _hex_to_image(hex_data: str, size: int = 16) -> Image.Image:
    """Convert hex-encoded RGB data to a PIL Image."""
    return Image.frombytes("RGB", (size, size), bytes.fromhex(hex_data))


_ICON_IMAGES_SD: Dict[str, Image.Image] = {
    "beacon": _hex_to_image(_BEACON_HEX, 16),
    "person": _hex_to_image(_PERSON_HEX, 16),
    "vehicle": _hex_to_image(_VEHICLE_HEX, 16),
    "animal": _hex_to_image(_ANIMAL_HEX, 16),
    "motion": _hex_to_image(_MOTION_HEX, 16),
    "warning": _hex_to_image(_WARNING_HEX, 16),
    "camera": _hex_to_image(_CAMERA_HEX, 16),
    "info": _hex_to_image(_INFO_HEX, 16),
}

_ICON_IMAGES_HD: Dict[str, Image.Image] = {
    "beacon": _hex_to_image(_BEACON_HD_HEX, 32),
    "person": _hex_to_image(_PERSON_HD_HEX, 32),
    "vehicle": _hex_to_image(_VEHICLE_HD_HEX, 32),
    "animal": _hex_to_image(_ANIMAL_HD_HEX, 32),
    "motion": _hex_to_image(_MOTION_HD_HEX, 32),
    "warning": _hex_to_image(_WARNING_HD_HEX, 32),
    "camera": _hex_to_image(_CAMERA_HD_HEX, 32),
    "info": _hex_to_image(_INFO_HD_HEX, 32),
}


def get_alert_icon(name: str, hd: bool = False) -> Optional[Image.Image]:
    """Get an alert icon by name.

    Args:
        name: Icon name ("beacon", "person", "vehicle", "animal",
              "motion", "warning", "camera", "info").
        hd: If True, return 32x32 HD icon. Otherwise 16x16 SD.

    Returns:
        PIL Image (16x16 or 32x32 RGB), or None if not found.
    """
    icons = _ICON_IMAGES_HD if hd else _ICON_IMAGES_SD
    img = icons.get(name)
    return img.copy() if img else None
